
import random

def make_random_map(star_count, 
                    min_x = 0,
                    max_x = 200,
                    min_y = 0, 
                    max_y = 200, 
                    min_size = 3.0, 
                    max_size = 15.0,
                    show = True):
    stars = []
    if show:
        print("# Random map")
        print("#  min_x = %i"%(min_x,))
        print("#  min_y = %i"%(min_y,))
        print("#  max_x = %i"%(max_x,))
        print("#  max_y = %i"%(max_y,))
        print("#  min_size = %.4f"%(min_size,))
        print("#  max_size = %.4f"%(max_size,))
        print("stars = ( ", end="")
    for i in range(star_count):
        x = random.randint(min_x, max_x)
        y = random.randint(min_y, max_y)
        s = random.random()*(max_size - min_size) + min_size
        stars.append((x,y,s))
        if show and i % 5 == 4:
            print(", ".join([f"({s[0]:5}, {s[1]:5}, {s[2]:7.4f})" for s in stars[-5:]]))
            print("          ", end="")
    if show:
        print(")")
    return stars


